ulary in Use · Exercise 5","instructions":"Complete the chart. Then complete the sentences with words from the chart.","implementationMode":"auto-scored","activityType":"typed_gap_fill","questions":[{"number":1,"prompt":"2 anxiety","questionType":"typed_short_answer","acceptedAnswers":["anxious"],"options":[]},{"number":2,"prompt":"3 attract","questionType":"typed_short_answer","acceptedAnswers":["attractive"],"options":[]},{"number":3,"prompt":"4 comfort","questionType":"typed_short_answer","acceptedAnswers":["comfortable"],"options":[]},{"number":4,"prompt":"5 disaster","questionType":"typed_short_answer","acceptedAnswers":["disastrous"],"options":[]},{"number":5,"prompt":"6 end","questionType":"typed_short_answer","acceptedAnswers":["endless"],"options":[]},{"number":6,"prompt":"7 event","questionType":"typed_short_answer","acceptedAnswers":["eventful"],"options":[]},{"number":7,"prompt":"8 harm","questionType":"typed_short_answer","acceptedAnswers":["harmful/harmless","harmful","harmless"],"options":[]},{"number":8,"prompt":"9 impress","questionType":"typed_short_answer","acceptedAnswers":["impressive"],"options":[]},{"number":9,"prompt":"10 memory","questionType":"typed_short_answer","acceptedAnswers":["memorable"],"options":[]},{"number":10,"prompt":"11 nation","questionType":"typed_short_answer","acceptedAnswers":["national"],"options":[]},{"number":11,"prompt":"12 season","questionType":"typed_short_answer","acceptedAnswers":["seasonal"],"options":[]}]},{"stableNormalizedId":"ultimate-b2-sb-u2-p3-o6","partNumber":3,"title":"Vocabulary in Use · Exercise 6","instructions":"Complete the sentences with the words in the box.","implementationMode":"auto-scored","activityType":"matching","questions":[{"number":1,"prompt":"2 Jobs in tourism tend to be ____ – not many resorts stay open all year round.","questionType":"matching","acceptedAnswers":["seasonal"],"options":["adventurous","anxious","attractive","comfortable","disastrous","endless","eventful","harmful","har