r","acceptedAnswers":["hadn’t been acting"],"options":[]},{"number":2,"prompt":"2 How many episodes of season two ____ (you / watch) by 10 pm last night?","questionType":"typed_short_answer","acceptedAnswers":["had you watched"],"options":[]},{"number":3,"prompt":"3 Some of the actors ____ (not finish) learning their lines before filming began.","questionType":"typed_short_answer","acceptedAnswers":["hadn’t finished"],"options":[]},{"number":4,"prompt":"4 We ____ (always / know) that Oliver would become a famous director.","questionType":"typed_short_answer","acceptedAnswers":["had always known"],"options":[]},{"number":5,"prompt":"5 He ____ (travel) for months and he just wanted to go home.","questionType":"typed_short_answer","acceptedAnswers":["had been travelling"],"options":[]},{"number":6,"prompt":"6 ____ (the passengers / wait) for a long time before the train arrived?","questionType":"typed_short_answer","acceptedAnswers":["Had the passengers been waiting"],"options":[]},{"number":7,"prompt":"7 She got lost because she ____ (forget) to take the map with her.","questionType":"typed_short_answer","acceptedAnswers":["had forgotten"],"options":[]},{"number":8,"prompt":"8 How long ____ (you / want) to live in Ireland before you moved there?","questionType":"typed_short_answer","acceptedAnswers":["had you wanted"],"options":[]}]},{"stableNormalizedId":"ultimate-b2-sb-u2-p12-o4","partNumber":12,"title":"Progress check 1 · Exercise 4","instructions":"Complete the second sentence so that it means the same as the first, using the word given. Do not change the word. Use between two and five words.","implementationMode":"auto-scored","activityType":"typed_gap_fill","questions":[{"number":1,"prompt":"1 Sarah talks about the famous actor she knows all the time! ALWAYS Sarah is ____ the famous actor she knows!","questionType":"typed_short_answer","acceptedAnswers":["always talking about"],"options":[]},{"number":2,"prompt":"2 I went jogging for an hour, so I was hot and tired. BEEN I was hot and tired because I ____ for an hour.","questionType":"typed_short_answer","acceptedAnswers":["had been jogging"],"options":[]},{"number":3,"prompt":"3 We disliked watching thrillers when we were younger. USE We ____ watching thrillers when we were younger.","questionType":"typed_short_answer","acceptedAnswers":["didn’t use to like"],"options":[]},{"number":4,"prompt":"4 Sorry, I completely forgot the time, so I missed the bus. REALISE Sorry, I ____ the time was, so I missed the bus.","questionType":"typed_short_answer","acceptedAnswers":["didn’t realise what"],"options":[]},{"number":5,"prompt":"5 The journalist interviewed the pilot and then posted his article. AFTER The journalist posted his article ____ the pilot.","questionType":"typed_short_answer","acceptedAnswers":["after he (had) interviewed","after he interviewed","after he had interviewed"],"options":[]},{"number":6,"prompt":"6 We used to cook on an open fire when we went camping. WOULD When we went camping, we ____ an open fire.","questionType":"typed_short_answer","acceptedAnswers":["would cook on"],"options":[]}]}]$unit2$::jsonb)
  loop
    lesson_slug_value := case
      when (activity_record->>'partNumber')::int = 2 then 'unit-2-reading'
      else 'unit-2-part-' || lpad(activity_record->>'partNumber', 2, '0')
    end;

    if (activity_record->>'partNumber')::int <> 2 then
      insert into lessons (unit_id, title, slug, lesson_type, sort_order, position, instructions, status)
      values (
        unit_uuid,
        'Unit 2 · Part ' || (activity_record->>'partNumber'),
        lesson_slug_value,
        'students-book-activity',
        (activity_record->>'partNumber')::int,
        (activity_record->>'partNumber')::int,
        'Evidence-backed Students Book Unit 2 activities.',
        'published'
      )
      on conflict (unit_id, slug) do update
      set title = excluded.title,
          lesson_type = excluded.lesson_type,
          sort_order = excluded.sort_order,
          position = excluded.position,
          instructions = excluded.instructions,
          status = excluded.status;
    end if;

    select id into lesson_uuid from lessons where unit_id = unit_uuid and slug = lesson_slug_value limit 1;

    insert into activities (
      lesson_id, slug, title, type, activity_type, instructions, estimated_minutes,
      content, content_json, settings_json, sort_order, is_assignable, is_demo_active
    )
    values (
      lesson_uuid,
      activity_record->>'stableNormalizedId',
      activity_record->>'title',
      activity_record->>'activityType',
      activity_record->>'activityType',
      coalesce(activity_record->>'instructions', ''),
      10,
      jsonb_build_object(
        'demoActivityKey', activity_record->>'stableNormalizedId',
        'publisherSourceActivityId', activity_record->>'stableNormalizedId',
        'implementationMode', activity_record->>'implementationMode',
        'feedbackSource', 'application-generated-neutral'
      ),
      jsonb_build_object(
        'demoActivityKey', activity_record->>'stableNormalizedId',
        'publisherSourceActivityId', activity_record->>'stableNormalizedId',
        'implementationMode', activity_record->>'implementationMode',
        'feedbackSource', 'application-generated-neutral'
      ),
      '{}'::jsonb,
      (activity_record->>'partNumber')::int * 100,
      true,
      true
    )
    on conflict (lesson_id, slug) do update
    set title = excluded.title,
        type = excluded.type,
        activity_type = excluded.activity_type,
        instructions = excluded.instructions,
        content = excluded.content,
        content_json = excluded.content_json,
        settings_json = excluded.settings_json,
        sort_order = excluded.sort_order,
        is_assignable = excluded.is_assignable,
        is_demo_active = excluded.is_demo_active;

    select id into activity_uuid from activities where lesson_id = lesson_uuid and slug = activity_record->>'stableNormalizedId' limit 1;

    for question_record in select value from jsonb_array_elements(activity_record->'questions')
    loop
      insert into questions (activity_id, question_number, prompt, question_type, content_json, feedback_json, sort_order)
      values (
        activity_uuid,
        (question_record->>'number')::int,
        question_record->>'prompt',
        question_record->>'questionType',
        '{}'::jsonb,
        jsonb_build_object(
          'acceptedAnswers', coalesce(question_record->'acceptedAnswers', '[]'::jsonb),
          'source', case when activity_record->>'implementationMode' = 'teacher-reviewed' then 'none-open-response' else 'decoded-publisher-explicit-answer' end,
          'feedbackSource', 'application-generated-neutral'
        ),
        (question_record->>'number')::int
      )
      on conflict (activity_id, question_number) do update
      set prompt = excluded.prompt,
          question_type = excluded.question_type,
          content_json = excluded.content_json,
          feedback_json = excluded.feedback_json,
          sort_order = excluded.sort_order;

      select id into question_uuid from questions
      where activity_id = activity_uuid and question_number = (question_record->>'number')::int
      limit 1;

      for option_record in
        select value, ordinal
        from jsonb_array_elements_text(coalesce(question_record->'options', '[]'::jsonb)) with ordinality as option_row(value, ordinal)
      loop
        insert into question_options (question_id, option_label, option_text, is_correct, sort_order)
        values (
          question_uuid,
          option_record.value,
          option_record.value,
          coalesce(question_record->'acceptedAnswers', '[]'::jsonb) ? option_record.value,
          option_record.ordinal
        )
        on conflict (question_id, option_label) do update
        set option_text = excluded.option_text,
            is_correct = excluded.is_correct,
            sort_order = excluded.sort_order;
      end loop;
    end loop;
  end loop;
end
